-- Settings › Contact gains recruitmentEmail, backfilled from the careers
-- page's seeded email (else the main email); the careers page's seeded phone
-- and email links become {mobile}/{mobileHref}/{recruitmentEmail} placeholders
-- so they follow Settings › Contact. A link the admin changed is left alone.
-- Published is only touched where it exists. Re-runnable.
UPDATE "settings" s
SET "draft" = jsonb_set(s."draft", '{recruitmentEmail}', to_jsonb(COALESCE(
  (SELECT p."draft" #>> '{job,email,label}' FROM "pages" p
   WHERE p."key" = 'careers' AND p."draft" #>> '{job,email,label}' ~ '^[^@{}\s]+@[^@{}\s]+$'),
  s."draft" ->> 'email')))
WHERE s."key" = 'contact'
  AND jsonb_typeof(s."draft") = 'object'
  AND NOT (s."draft" ? 'recruitmentEmail')
  AND s."draft" ? 'email';--> statement-breakpoint
UPDATE "settings" s
SET "published" = jsonb_set(s."published", '{recruitmentEmail}', to_jsonb(COALESCE(
  (SELECT p."published" #>> '{job,email,label}' FROM "pages" p
   WHERE p."key" = 'careers' AND p."published" #>> '{job,email,label}' ~ '^[^@{}\s]+@[^@{}\s]+$'),
  (SELECT p."draft" #>> '{job,email,label}' FROM "pages" p
   WHERE p."key" = 'careers' AND p."draft" #>> '{job,email,label}' ~ '^[^@{}\s]+@[^@{}\s]+$'),
  s."published" ->> 'email')))
WHERE s."key" = 'contact'
  AND s."published" IS NOT NULL
  AND jsonb_typeof(s."published") = 'object'
  AND NOT (s."published" ? 'recruitmentEmail')
  AND s."published" ? 'email';--> statement-breakpoint
UPDATE "pages" p
SET "draft" = CASE WHEN p."draft" #> '{apply,sidebar,email}' = '{"label":"jobs@cleaningpartners.ie","href":"mailto:jobs@cleaningpartners.ie"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{apply,sidebar,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{job,email}' = '{"label":"jobs@cleaningpartners.ie","href":"mailto:jobs@cleaningpartners.ie"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{job,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END, '{job,phone}', '{"label":"{mobile}","href":"{mobileHref}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END END, '{job,email}', '{"label":"{recruitmentEmail}","href":"mailto:{recruitmentEmail}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{job,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END, '{job,phone}', '{"label":"{mobile}","href":"{mobileHref}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END END END, '{apply,sidebar,phone}', '{"label":"{mobile}","href":"{mobileHref}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{job,email}' = '{"label":"jobs@cleaningpartners.ie","href":"mailto:jobs@cleaningpartners.ie"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{job,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END, '{job,phone}', '{"label":"{mobile}","href":"{mobileHref}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END END, '{job,email}', '{"label":"{recruitmentEmail}","href":"mailto:{recruitmentEmail}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{job,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END, '{job,phone}', '{"label":"{mobile}","href":"{mobileHref}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END END END END, '{apply,sidebar,email}', '{"label":"{recruitmentEmail}","href":"mailto:{recruitmentEmail}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{apply,sidebar,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{job,email}' = '{"label":"jobs@cleaningpartners.ie","href":"mailto:jobs@cleaningpartners.ie"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{job,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858