) ELSE CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END END, '{job,email}', '{"label":"{recruitmentEmail}","href":"mailto:{recruitmentEmail}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{job,phone}' = '{"label":"(085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END, '{job,phone}', '{"label":"{mobile}","href":"{mobileHref}"}'::jsonb) ELSE CASE WHEN p."draft" #> '{talentPool,call}' = '{"label":"Call (085) 806 2369","href":"tel:+353858062369"}'::jsonb THEN jsonb_set(p."draft", '{talentPool,call}', '{"label":"Call {mobile}","href":"{mobileHref}"}'::jsonb) ELSE p."draft" END END END END END
WHERE p."key" = 'careers';--> statement-breakpoint
